{"content": "import React, { useState, useRef, useEffect } from 'react'
import { Canvas } from '@react-three/fiber'
import { OrbitControls } from '@react-three/drei'
import TugOfWarScene from './TugOfWarScene'

const TugOfWarGame = () => {
  const [ropePosition, setRopePosition] = useState(0) // -5 to 5, 0 is center
  const [redStrength, setRedStrength] = useState(0)
  const [blueStrength, setBlueStrength] = useState(0)
  const [winner, setWinner] = useState(null)
  const [isGameActive, setIsGameActive] = useState(true)

  const strengthDecayRef = useRef()

  // Decay strength over time
  useEffect(() => {
    strengthDecayRef.current = setInterval(() => {
      setRedStrength(prev => Math.max(0, prev - 1))
      setBlueStrength(prev => Math.max(0, prev - 1))
    }, 100)

    return () => clearInterval(strengthDecayRef.current)
  }, [])

  // Update rope position based on strength difference
  useEffect(() => {
    if (!isGameActive) return

    const strengthDiff = blueStrength - redStrength
    const newPosition = ropePosition + (strengthDiff * 0.01)
    const clampedPosition = Math.max(-5, Math.min(5, newPosition))

    setRopePosition(clampedPosition)

    // Check for winner
    if (clampedPosition <= -4.5) {
      setWinner('Red Team')
      setIsGameActive(false)
    } else if (clampedPosition >= 4.5) {
      setWinner('Blue Team')
      setIsGameActive(false)
    }
  }, [redStrength, blueStrength, ropePosition, isGameActive])

  const handleRedPull = () => {
    if (!isGameActive) return
    setRedStrength(prev => Math.min(100, prev + 15))
  }

  const handleBluePull = () => {
    if (!isGameActive) return
    setBlueStrength(prev => Math.min(100, prev + 15))
  }

  const resetGame = () => {
    setRopePosition(0)
    setRedStrength(0)
    setBlueStrength(0)
    setWinner(null)
    setIsGameActive(true)
  }

  const getPositionText = () => {
    if (ropePosition < -2) return "Red Team Advantage!"
    if (ropePosition > 2) return "Blue Team Advantage!"
    return "Even Match!"
  }

  return (
    <>
      <Canvas
        camera={{ position: [0, 5, 10], fov: 60 }}
        style={{ width: '100vw', height: '100vh' }}
      >
        <ambientLight intensity={0.6} />
        <directionalLight position={[10, 10, 5]} intensity={1} />
        <TugOfWarScene ropePosition={ropePosition} />
        <OrbitControls
          enablePan={false}
          enableZoom={true}
          enableRotate={true}
          maxPolarAngle={Math.PI / 2}
          minDistance={5}
          maxDistance={20}
        />
      </Canvas>

      <div className="game-ui">
        <div className="game-header">
          <h1 className="game-title">🐔 Chicken Pit Tug O' War 🐔</h1>
          <div className="game-status">{getPositionText()}</div>
        </div>

        <div className="controls">
          <div className="team-controls team-red">
            <div className="team-name">🔴 Red Team</div>
            <button className="pull-button" onClick={handleRedPull} disabled={!isGameActive}>
              Pull!
            </button>
            <div className="strength-meter">
              <div 
                className="strength-fill" 
                style={{ width: `${redStrength}%` }}
              />
            </div>
            <div>Strength: {redStrength}</div>
          </div>

          <div className="center-indicator">
            <div className="rope-position">
              Rope Position: {ropePosition.toFixed(1)}
            </div>
            <button className="reset-button" onClick={resetGame}>
              Reset Game
            </button>
          </div>

          <div className="team-controls team-blue">
            <div className="team-name">🔵 Blue Team</div>
            <button className="pull-button" onClick={handleBluePull} disabled={!isGameActive}>
              Pull!
            </button>
            <div className="strength-meter">
              <div 
                className="strength-fill" 
                style={{ width: `${blueStrength}%` }}
              />
            </div>
            <div>Strength: {blueStrength}</div>
          </div>
        </div>
      </div>

      {winner && (
        <div className="winner-announcement">
          🎉 {winner} Wins! 🎉
        </div>
      )}
    </>
  )
}

export default TugOfWarGame", "filePath": "/Users/rais/Desktop/chicken-pit/src/components/TugOfWarGame.jsx"}

{"content": "import React, { useRef, useMemo } from 'react'
import { useFrame } from '@react-three/fiber'
import { Text, Box, Cylinder, Sphere } from '@react-three/drei'
import * as THREE from 'three'

const Player = ({ position, color, isLeft }) => {
  const meshRef = useRef()

  useFrame((state) => {
    if (meshRef.current) {
      // Add subtle breathing animation
      meshRef.current.scale.y = 1 + Math.sin(state.clock.elapsedTime * 2) * 0.05
    }
  })

  return (
    <group position={position}>
      {/* Player body */}
      <Box ref={meshRef} args={[0.8, 1.5, 0.4]} position={[0, 0.75, 0]}>
        <meshLambertMaterial color={color} />
      </Box>

      {/* Player head */}
      <Sphere args={[0.3]} position={[0, 1.8, 0]}>
        <meshLambertMaterial color={color === '#ff4757' ? '#ff6b6b' : '#4834d4'} />
      </Sphere>

      {/* Arms */}
      <Box args={[0.2, 0.8, 0.2]} position={[isLeft ? 0.5 : -0.5, 1, 0.3]}>
        <meshLambertMaterial color={color} />
      </Box>
      <Box args={[0.2, 0.8, 0.2]} position={[isLeft ? -0.5 : 0.5, 1, 0.3]}>
        <meshLambertMaterial color={color} />
      </Box>

      {/* Legs */}
      <Box args={[0.25, 0.8, 0.25]} position={[-0.2, -0.4, 0]}>
        <meshLambertMaterial color={color} />
      </Box>
      <Box args={[0.25, 0.8, 0.25]} position={[0.2, -0.4, 0]}>
        <meshLambertMaterial color={color} />
      </Box>
    </group>
  )
}

const Rope = ({ ropePosition }) => {
  const ropeRef = useRef()

  // Create rope segments
  const segments = useMemo(() => {
    const segmentCount = 20
    const totalLength = 10
    const segmentLength = totalLength / segmentCount

    return Array.from({ length: segmentCount }, (_, i) => {
      const x = (i - segmentCount / 2) * segmentLength + ropePosition
      const y = 1.5 + Math.sin((i / segmentCount) * Math.PI * 2) * 0.1 // Slight curve
      return [x, y, 0]
    })
  }, [ropePosition])

  return (
    <group ref={ropeRef}>
      {segments.map((position, index) => (
        <Cylinder
          key={index}
          args={[0.05, 0.05, 0.4]}
          position={position}
          rotation={[0, 0, Math.PI / 2]}
        >
          <meshLambertMaterial color="#8B4513" />
        </Cylinder>
      ))}

      {/* Center marker on rope */}
      <Sphere args={[0.1]} position={[ropePosition, 1.5, 0]}>
        <meshLambertMaterial color="#FFD700" />
      </Sphere>
    </group>
  )
}

const Ground = () => {
  return (
    <group>
      {/* Main ground */}
      <Box args={[20, 0.2, 10]} position={[0, -0.1, 0]}>
        <meshLambertMaterial color="#90EE90" />
      </Box>

      {/* Center line */}
      <Box args={[0.1, 0.1, 8]} position={[0, 0.1, 0]}>
        <meshLambertMaterial color="#FFFFFF" />
      </Box>

      {/* Goal lines */}
      <Box args={[0.1, 0.1, 8]} position={[-4.5, 0.1, 0]}>
        <meshLambertMaterial color="#FF0000" />
      </Box>
      <Box args={[0.1, 0.1, 8]} position={[4.5, 0.1, 0]}>
        <meshLambertMaterial color="#0000FF" />
      </Box>
    </group>
  )
}

const TugOfWarScene = ({ ropePosition }) => {
  return (
    <>
      <Ground />

      {/* Red team players */}
      <Player position={[-6, 0, 1]} color="#ff4757" isLeft={true} />
      <Player position={[-7, 0, -1]} color="#ff4757" isLeft={true} />
      <Player position={[-8, 0, 0]} color="#ff4757" isLeft={true} />

      {/* Blue team players */}
      <Player position={[6, 0, 1]} color="#3742fa" isLeft={false} />
      <Player position={[7, 0, -1]} color="#3742fa" isLeft={false} />
      <Player position={[8, 0, 0]} color="#3742fa" isLeft={false} />

      {/* Rope */}
      <Rope ropePosition={ropePosition} />

      {/* Team labels */}
      <Text
        position={[-6, 3, 0]}
        fontSize={0.8}
        color="#ff4757"
        anchorX="center"
        anchorY="middle"
      >
        RED TEAM
      </Text>

      <Text
        position={[6, 3, 0]}
        fontSize={0.8}
        color="#3742fa"
        anchorX="center"
        anchorY="middle"
      >
        BLUE TEAM
      </Text>

      {/* Decorative elements */}
      {/* Crowd/Spectators */}
      <Sphere args={[0.3]} position={[-10, 1, 3]}>
        <meshLambertMaterial color="#FFB6C1" />
      </Sphere>
      <Sphere args={[0.3]} position={[-10, 1, -3]}>
        <meshLambertMaterial color="#98FB98" />
      </Sphere>
      <Sphere args={[0.3]} position={[10, 1, 3]}>
        <meshLambertMaterial color="#87CEEB" />
      </Sphere>
      <Sphere args={[0.3]} position={[10, 1, -3]}>
        <meshLambertMaterial color="#DDA0DD" />
      </Sphere>
    </>
  )
}

