const Player = ({ position, color, isLeft, ropePosition, winner, isGameActive }) => {
  const meshRef = useRef()
  const groupRef = useRef()

  useFrame((state) => {
    if (meshRef.current) {
      // Add subtle breathing animation
      meshRef.current.scale.y = 1 + Math.sin(state.clock.elapsedTime * 2) * 0.05
    }

    if (groupRef.current) {
      // Check if this team should fall into the hole
      const isRedTeam = color === '#ff4757'
      const shouldFall = !isGameActive && 
        ((winner === 'Blue Team' && isRedTeam) || 
         (winner === 'Red Team' && !isRedTeam))

      if (shouldFall) {
        // Falling animation - move toward center and down
        const currentY = groupRef.current.position.y
        const targetY = -5 // Fall into the hole
        const currentX = groupRef.current.position.x
        const targetX = 0 // Move toward center of hole

        if (currentY > targetY) {
          // Fall down with acceleration
          groupRef.current.position.y = Math.max(targetY, currentY - 0.1)
          // Move toward center
          groupRef.current.position.x = currentX + (targetX - currentX) * 0.02
          // Add spinning effect while falling
          groupRef.current.rotation.z += 0.1
          groupRef.current.rotation.x += 0.05
        }
      } else if (isGameActive) {
        // Normal leaning effect during game
        const leanAmount = Math.abs(ropePosition) * 0.05
        const leanDirection = ropePosition > 0 ? (isLeft ? -1 : 1) : (isLeft ? 1 : -1)
        groupRef.current.rotation.z = leanDirection * leanAmount
      }
    }
  })

  return (
    <group ref={groupRef} position={position}>
      {/* Player body */}
      <Box ref={meshRef} args={[0.8, 1.5, 0.4]} position={[0, 0.75, 0]}>
        <meshLambertMaterial color={color} />
      </Box>

      {/* Player head */}
      <Sphere args={[0.3]} position={[0, 1.8, 0]}>
        <meshLambertMaterial color={color === '#ff4757' ? '#ff6b6b' : '#4834d4'} />
      </Sphere>

      {/* Arms - positioned for pulling */}
      <Box args={[0.2, 0.8, 0.2]} position={[isLeft ? 0.5 : -0.5, 1, 0.3]}>
        <meshLambertMaterial color={color} />
      </Box>
      <Box args={[0.2, 0.8, 0.2]} position={[isLeft ? -0.5 : 0.5, 1, 0.3]}>
        <meshLambertMaterial color={color} />
      </Box>

      {/* Legs */}
      <Box args={[0.25, 0.8, 0.25]} position={[-0.2, -0.4, 0]}>
        <meshLambertMaterial color={color} />
      </Box>
      <Box args={[0.25, 0.8, 0.25]} position={[0.2, -0.4, 0]}>
        <meshLambertMaterial color={color} />
      </Box>
    </group>
  )
}

